42|// Explicit sticky pick wins; else the active skin's default (unknown or
43|// missing skin ignored); else denslow.
44|export function resolveEffectiveStyle(
45|  explicit: StyleChoice | undefined,
46|  skin: string | undefined,
47|): StyleChoice {
48|  if (explicit !== undefined) return explicit;
49|  if (skin !== undefined) {
50|    const fallback = (SKIN_DEFAULT_IMAGE_STYLE as Record<string, ImageStylePresetId>)[skin];
