70|// Base error lives here (not in core/images) so this self-contained module
71|// can throw it without a module cycle; core/images re-exports it.
72|export class ImageValidationError extends Error {
73|  constructor() {
74|    super("invalid image request");
75|    this.name = "ImageValidationError";
76|  }
77|}
78|
79|export class ImageStyleError extends ImageValidationError {
80|  constructor() {
81|    super();
82|    this.name = "ImageStyleError";
83|  }
84|}
85|
86|// Whole words and phrases rejected on the normalized custom text: prompt
87|// override, nsfw, and people/brand guards. Entries stay literal lowercase
88|// words and spaces, matched with word boundaries only.
89|const DENY_WORDS = [
90|  "ignore", "disregard", "forget", "instead", "instruction", "instructions",
91|  "prompt", "system", "override", "previous", "assistant", "text", "caption",
92|  "captions", "letter", "letters", "lettering", "word", "words", "write",
93|  "written", "logo", "logos", "watermark",
94|  "nude", "nudity", "naked", "nsfw", "sex", "sexy", "sexual", "porn",
95|  "erotic", "hentai", "lingerie", "gore", "gory", "bloody",
96|  "by", "artist", "studio", "celebrity", "ghibli", "miyazaki", "disney",
97|  "pixar", "dreamworks", "marvel", "banksy", "toriyama", "burton", "mgm",
98|  "garland", "ruby",
99|];
100|
101|const DENY_PHRASES = ["style of", "in the style", "photo of"];
102|
103|const DENY_RE = new RegExp(`\\b(?:${[...DENY_WORDS, ...DENY_PHRASES].join("|")})\\b`, "u");
104|
105|// Null means rejected. Control and format chars become spaces so newlines,
106|// tabs, zero-width, and bidi marks cannot smuggle extra instructions.
107|export function normalizeCustomStyle(raw: string): string | null {
108|  const normalized = raw
109|    .normalize("NFKC")
110|    .replace(/[\p{Cc}\p{Cf}]/gu, " ")
111|    .replace(/\s+/g, " ")
112|    .trim()
113|    .toLowerCase();
114|  if (normalized.length < 2 || normalized.length > MAX_CUSTOM_STYLE_CHARS) return null;
115|  if (!/^[\p{L}\p{N} ,.'&-]+$/u.test(normalized)) return null;
116|  if (DENY_RE.test(normalized)) return null;
117|  return normalized;
118|}
119|
120|// Undefined means default. Exact shapes only: one key, a known preset id
121|// or a normalizable custom string; anything else throws ImageStyleError.
122|// {preset:"denslow"} returns undefined, so it keys like an omitted style.
123|export function parseStyleChoice(json: unknown): ImageStyle | undefined {
124|  if (json === undefined) return undefined;
125|  if (typeof json !== "object" || json === null || Array.isArray(json)) throw new ImageStyleError();
126|  const rec = json as Record<string, unknown>;
127|  if (Object.keys(rec).length !== 1) throw new ImageStyleError();
128|  if ("preset" in rec) {
129|    if (typeof rec.preset !== "string") throw new ImageStyleError();
130|    if (rec.preset === DEFAULT_IMAGE_STYLE) return undefined;
131|    if (!isPresetId(rec.preset)) throw new ImageStyleError();
132|    return { kind: "preset", id: rec.preset };
133|  }
134|  if ("custom" in rec) {
135|    if (typeof rec.custom !== "string") throw new ImageStyleError();
136|    const text = normalizeCustomStyle(rec.custom);
137|    if (text === null) throw new ImageStyleError();
138|    return { kind: "custom", text };
139|  }
140|  throw new ImageStyleError();
141|}
