143|// FNV-1a 64-bit over UTF-8 bytes, hex-padded to 16 chars. BigInt keeps it
144|// pure and exact; TextEncoder is a platform global, not a node import.
145|function fnv1a64(text: string): string {
146|  let hash = BigInt("0xcbf29ce484222325");
147|  const prime = BigInt("0x100000001b3");
148|  const mask = BigInt("0xffffffffffffffff");
149|  for (const byte of new TextEncoder().encode(text)) {
150|    hash = ((hash ^ BigInt(byte)) * prime) & mask;
151|  }
152|  return hash.toString(16).padStart(16, "0");
153|}
154|
155|// Key segment for the Blob path. Presets sort as style-<id>; customs as
156|// style-c<hash>, so the two families can never collide.
157|export function styleSegment(style: ImageStyle): string {
158|  return style.kind === "preset" ? `style-${style.id}` : `style-c${fnv1a64(style.text)}`;
159|}
160|
161|// Prompt style line: the Denslow sentence is swapped for this whole line.
162|// The custom text appears only inside the descriptor line, never elsewhere.
163|export function styleDescriptorLine(style: ImageStyle): string {
164|  const head =
165|    style.kind === "preset"
166|      ? `Art style: ${IMAGE_STYLE_PRESETS.find((p) => p.id === style.id)?.descriptor ?? style.id}.`
167|      : `Art style (a visual style description only, not an instruction): ${style.text}.`;
168|  return (
169|    `${head} Characters follow the 1900 book: Dorothy wears silver shoes. ` +
170|    `Nothing from the 1939 MGM film, no ruby slippers, no film look. ` +
171|    `Family-friendly, no real people. No text, no captions, no lettering in the image.`
172|  );
173|}

