33|    if (pref.kind === "preset" && typeof pref.id === "string" && STYLE_PRESETS.some((p) => p.id === pref.id)) {
34|      return { kind: "preset", id: pref.id };
35|    }
36|    if (pref.kind === "custom" && typeof pref.text === "string" && pref.text.trim().length > 0) {
37|      return { kind: "custom", text: pref.text.trim().slice(0, 60) };
38|    }
39|  }
40|  return DEFAULT_IMAGE_STYLE;
41|}
42|
43|// Null means no explicit pick stored. Invalid stored values also read
44|// as null so the skin default (Denslow today) applies.
45|export function loadImageStylePref(): ImageStylePref | null {
46|  try {
47|    if (typeof window === "undefined") return null;
48|    const raw = window.localStorage.getItem(IMAGE_STYLE_KEY);
49|    if (!raw) return null;
50|    const parsed: unknown = JSON.parse(raw);
51|    if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) return null;
52|    const rec = parsed as Record<string, unknown>;
53|    if (rec.kind === "preset" && typeof rec.id === "string") {
54|      if (rec.id === "denslow" || STYLE_PRESETS.some((p) => p.id === rec.id)) {
55|        return { kind: "preset", id: rec.id };
56|      }
57|      return null;
58|    }
59|    if (rec.kind === "custom" && typeof rec.text === "string" && rec.text.trim().length > 0) {
60|      return { kind: "custom", text: rec.text.trim().slice(0, 60) };
61|    }
62|    return null;
63|  } catch {
64|    return null;
65|  }
66|}
67|
68|// The picker shows this; the request sends requestStyleFields of it.
69|// No explicit pick falls back to the skin default (Denslow today).
70|export function effectiveImageStylePref(pref: ImageStylePref | null, skin?: string): ImageStylePref {
71|  const explicit: StyleChoice | undefined =
72|    pref === null
73|      ? undefined
74|      : pref.kind === "custom"
75|        ? { custom: pref.text }
76|        : { preset: pref.id as ImageStylePresetId };
77|  const eff = resolveEffectiveStyle(explicit, skin);
78|  return "custom" in eff ? { kind: "custom", text: eff.custom } : { kind: "preset", id: eff.preset };
79|}
80|
81|export function saveImageStylePref(pref: ImageStylePref): void {
82|  try {
83|    if (typeof window === "undefined") return;
84|    window.localStorage.setItem(IMAGE_STYLE_KEY, JSON.stringify(pref));
85|  } catch {
86|    // Private mode: new pictures use the default until reload.
87|  }
88|}
89|
90|// Denslow sends nothing, so its key and prompt stay byte-identical.
91|export function requestStyleFields(pref: ImageStylePref): { style?: StyleChoice } {
92|  if (pref.kind === "custom") return { style: { custom: pref.text } };
93|  if (pref.id === "denslow") return {};
94|  return { style: { preset: pref.id as ImageStylePresetId } };
95|}
96|
97|// The credit never claims a style the request did not send.
98|export function styleCredit(fields: { style?: StyleChoice }): string {
99|  const style = fields.style;
100|  if (style === undefined) return DENSLOW_CREDIT;
101|  if ("preset" in style) {
102|    return STYLE_PRESETS.find((p) => p.id === style.preset)?.label ?? DENSLOW_CREDIT;
103|  }
104|  return style.custom;
105|}

