1|// User-selectable image style. Pure: no node imports, no env reads, no
2|// network, so app/ can import it directly. The server normalizes and
3|// rejects custom text at parse time; the client only persists a choice.
4|export interface ImageStylePreset {
5|  id: string;
6|  label: string;
7|  descriptor: string;
8|}
9|
10|export const IMAGE_STYLE_PRESETS = [
11|  { id: "denslow", label: "Denslow ink (1900)", descriptor: "faithful 1900 first-edition book illustration" },
12|  { id: "realistic", label: "Realistic", descriptor: "realistic painterly illustration, natural light, lifelike detail" },
13|  { id: "anime", label: "Anime", descriptor: "anime-style illustration, clean line art, cel shading, vivid color" },
14|  { id: "pencil", label: "Pencil sketch", descriptor: "graphite pencil sketch on cream paper, fine hatching, mostly monochrome" },
15|  { id: "watercolor", label: "Watercolor", descriptor: "soft translucent washes, gentle storybook palette, light pencil underdrawing, visible paper texture" },
16|  { id: "storybook", label: "Storybook", descriptor: "modern children's picture-book illustration, soft gouache, warm colors" },
17|  { id: "comic", label: "Comic book", descriptor: "comic-book art, bold inks, halftone shading, strong flat colors" },
18|  { id: "oil", label: "Oil painting", descriptor: "classical oil painting, rich brushwork, warm glazes" },
19|  { id: "woodcut", label: "Woodcut", descriptor: "woodcut print, carved black lines, two-color print" },
20|  { id: "pen-pencil", label: "Pen and pencil", descriptor: "blue ballpoint pen line drawing with loose pencil shading on notebook paper, hand-drawn doodle feel" },
21|] as const;
22|
23|// The denslow descriptor is unused: denslow parses to undefined, so the
24|// prompt and key stay exactly as today.
25|export type ImageStylePresetId = (typeof IMAGE_STYLE_PRESETS)[number]["id"];
26|
27|export const DEFAULT_IMAGE_STYLE = "denslow" as const;
28|
29|// Prototype skins only, not built in the UI. One entry per skin maps it
30|// to its default preset; a future skin adds one entry here.
31|export const SKIN_IDS = ["engraving", "watercolor", "ink"] as const;
32|export type SkinId = (typeof SKIN_IDS)[number];
33|export const SKIN_DEFAULT_IMAGE_STYLE: Record<SkinId, ImageStylePresetId> = {
34|  engraving: "denslow",
35|  watercolor: "watercolor",
36|  ink: "pen-pencil",
37|};
38|
39|// Explicit sticky pick wins; else the active skin's default (unknown or
40|// missing skin ignored); else denslow.
41|export function resolveEffectiveStyle(
42|  explicit: StyleChoice | undefined,
43|  skin: string | undefined,
44|): StyleChoice {
45|  if (explicit !== undefined) return explicit;
46|  if (skin !== undefined) {
47|    const fallback = (SKIN_DEFAULT_IMAGE_STYLE as Record<string, ImageStylePresetId>)[skin];
48|    if (fallback !== undefined) return { preset: fallback };
49|  }
50|  return { preset: DEFAULT_IMAGE_STYLE };
51|}
52|
53|export const MAX_CUSTOM_STYLE_CHARS = 60;
54|
55|// Wire shape from the client. The parsed form replaces it server-side.
56|export type StyleChoice = { preset: ImageStylePresetId } | { custom: string };
57|
58|// Parsed style stored on the request. Undefined means the default.
59|export type ImageStyle = { kind: "preset"; id: ImageStylePresetId } | { kind: "custom"; text: string };
60|
61|const PRESET_IDS = new Set<string>(IMAGE_STYLE_PRESETS.map((p) => p.id));
62|
63|function isPresetId(id: string): id is ImageStylePresetId {
64|  return PRESET_IDS.has(id);
65|}
66|
67|// Base error lives here (not in core/images) so this self-contained module
68|// can throw it without a module cycle; core/images re-exports it.
69|export class ImageValidationError extends Error {
70|  constructor() {
71|    super("invalid image request");
72|    this.name = "ImageValidationError";
73|  }
74|}
75|
76|export class ImageStyleError extends ImageValidationError {
77|  constructor() {
78|    super();
79|    this.name = "ImageStyleError";
80|  }
81|}
82|
83|// Whole words and phrases rejected on the normalized custom text: prompt
84|// override, nsfw, and people/brand guards. Entries stay literal lowercase
85|// words and spaces, matched with word boundaries only.
86|const DENY_WORDS = [
87|  "ignore", "disregard", "forget", "instead", "instruction", "instructions",
88|  "prompt", "system", "override", "previous", "assistant", "text", "caption",
89|  "captions", "letter", "letters", "lettering", "word", "words", "write",
90|  "written", "logo", "logos", "watermark",
91|  "nude", "nudity", "naked", "nsfw", "sex", "sexy", "sexual", "porn",
92|  "erotic", "hentai", "lingerie", "gore", "gory", "bloody",
93|  "by", "artist", "studio", "celebrity", "ghibli", "miyazaki", "disney",
94|  "pixar", "dreamworks", "marvel", "banksy", "toriyama", "burton", "mgm",
95|  "garland", "ruby",
96|];
97|
98|const DENY_PHRASES = ["style of", "in the style", "photo of"];
99|
100|const DENY_RE = new RegExp(`\\b(?:${[...DENY_WORDS, ...DENY_PHRASES].join("|")})\\b`, "u");
101|
102|// Null means rejected. Control and format chars become spaces so newlines,
103|// tabs, zero-width, and bidi marks cannot smuggle extra instructions.
104|export function normalizeCustomStyle(raw: string): string | null {
105|  const normalized = raw
106|    .normalize("NFKC")
107|    .replace(/[\p{Cc}\p{Cf}]/gu, " ")
108|    .replace(/\s+/g, " ")
109|    .trim()
110|    .toLowerCase();
111|  if (normalized.length < 2 || normalized.length > MAX_CUSTOM_STYLE_CHARS) return null;
112|  if (!/^[\p{L}\p{N} ,.'&-]+$/u.test(normalized)) return null;
113|  if (DENY_RE.test(normalized)) return null;
114|  return normalized;
115|}
116|
117|// Undefined means default. Exact shapes only: one key, a known preset id
118|// or a normalizable custom string; anything else throws ImageStyleError.
119|// {preset:"denslow"} returns undefined, so it keys like an omitted style.
120|export function parseStyleChoice(json: unknown): ImageStyle | undefined {
121|  if (json === undefined) return undefined;
122|  if (typeof json !== "object" || json === null || Array.isArray(json)) throw new ImageStyleError();
123|  const rec = json as Record<string, unknown>;
124|  if (Object.keys(rec).length !== 1) throw new ImageStyleError();
125|  if ("preset" in rec) {
126|    if (typeof rec.preset !== "string") throw new ImageStyleError();
127|    if (rec.preset === DEFAULT_IMAGE_STYLE) return undefined;
128|    if (!isPresetId(rec.preset)) throw new ImageStyleError();
129|    return { kind: "preset", id: rec.preset };
130|  }
131|  if ("custom" in rec) {
132|    if (typeof rec.custom !== "string") throw new ImageStyleError();
133|    const text = normalizeCustomStyle(rec.custom);
134|    if (text === null) throw new ImageStyleError();
135|    return { kind: "custom", text };
136|  }
137|  throw new ImageStyleError();
